from __future__ import annotations

import inspect
import posixpath
import tarfile
from pathlib import Path

_EXTRACT_TAKES_FILTER = "filter" in inspect.signature(tarfile.TarFile.extract).parameters


def install_bundle(archive_path: str | Path, destination: str | Path) -> list[str]:
    """Unpack a tar.gz theme bundle below ``destination``.

    Regular members are installed and their POSIX names are returned sorted
    lexicographically; directories are installed but not reported, and an
    empty bundle yields an empty list. A member that is absolute, escapes the
    destination, or is neither a regular file nor a directory is rejected with
    ``ValueError`` before anything is written.
    """
    destination = Path(destination)
    root = destination.resolve()

    with tarfile.open(archive_path, "r:gz") as archive:
        validated: list[tuple[tarfile.TarInfo, str]] = []
        for member in archive.getmembers():
            name = _validated_name(member, root)
            if name is not None:
                validated.append((member, name))
        installed = [name for member, name in validated if member.isfile()]
        for member, _name in validated:
            _extract(archive, member, destination)

    return sorted(installed)


def _validated_name(member: tarfile.TarInfo, root: Path) -> str | None:
    """Return the installable POSIX name of ``member``, or None to skip it."""
    if not member.name:
        raise ValueError("invalid archive member")
    name = posixpath.normpath(member.name)
    if name == ".":
        return None
    if name.startswith("/") or name == ".." or name.startswith("../"):
        raise ValueError("invalid archive member")
    if not (member.isfile() or member.isdir()):
        raise ValueError("unsupported archive member")
    try:
        (root / name).resolve().relative_to(root)
    except ValueError:
        raise ValueError("invalid archive member") from None
    return name


def _extract(archive: tarfile.TarFile, member: tarfile.TarInfo, destination: Path) -> None:
    if _EXTRACT_TAKES_FILTER:
        archive.extract(member, path=destination, filter="data")
    else:
        archive.extract(member, path=destination)
